INSERT INTO feed (social_account_id, content, posted_date, author_id, author_name, remote_url, remote_id, preview_url, preview_title, preview_description, preview_image_url) VALUES
  (1, 'Just tried the new Autumn Blend from @acmeroasters and wow, that hazelnut finish.', NOW() - INTERVAL 25 MINUTE, 'demo-author-1', 'Riley Example', 'https://mastodon.example.org/@riley/demo-2001', 'demo-2001', '', '', '', ''),
  (2, 'Anyone know a good spot for coffee near the harbour? Need somewhere to work for a few hours.', NOW() - INTERVAL 50 MINUTE, 'demo-author-2', 'Morgan Sample', 'https://bsky.example.com/profile/morgan.example.com/post/demo-2002', 'demo-2002', '', '', '', ''),
  (1, 'Reminder: the farmers market moves indoors from next week. Same stalls, warmer hands.', NOW() - INTERVAL 2 HOUR, 'demo-author-3', 'Harbour Street Market', 'https://mastodon.example.org/@market/demo-2003', 'demo-2003', '', '', '', ''),
  (3, 'Ranking every flat white in town so you don''t have to. Thread below.', NOW() - INTERVAL 3 HOUR, 'demo-author-4', 'Casey Demo', 'https://x.example.com/caseydemo/status/demo-2004', 'demo-2004', '', '', '', ''),
  (2, 'Latte art practice, day 12. It is starting to look like a tulip. Mostly.', NOW() - INTERVAL 5 HOUR, 'demo-author-5', 'Jamie Placeholder', 'https://bsky.example.com/profile/jamie.example.com/post/demo-2005', 'demo-2005', '', '', '', ''),
